(()=>{
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
window.FyersMarketChart={mount(host,{symbol,onSymbol,onPlan}){
 host.innerHTML='<div class="market-controls"><label>Exchange segment<select id="fcSegment">'+[['NSE_CM','NSE stocks & indices'],['BSE_CM','BSE stocks & indices'],['NSE_FO','NSE futures & options'],['BSE_FO','BSE futures & options'],['MCX_COM','MCX commodities'],['NSE_CD','NSE currencies']].map(([v,t])=>'<option value="'+v+'">'+t+'</option>').join('')+'</select></label><label>Find instrument<input id="fcSearch" placeholder="Company name or symbol" maxlength="80"></label><button id="fcFind">Search FYERS instruments</button></div><p id="fcSearchStatus" role="status"></p><label>Search results<select id="fcResults"><option value="">Search to find an instrument</option></select></label><div class="market-controls"><label>Exact FYERS symbol<input id="fcSymbol" value="'+esc(symbol)+'" maxlength="70"></label><label>Timeframe<select id="fcResolution">'+[['1','1m'],['3','3m'],['5','5m'],['15','15m'],['30','30m'],['60','1h'],['120','2h'],['240','4h'],['D','1D']].map(([v,t])=>'<option value="'+v+'" '+(v==='60'?'selected':'')+'>'+t+'</option>').join('')+'</select></label><button id="fcLoad">Load / refresh FYERS chart</button><label>Chart type<select id="fcType"><option value="candles">Candles</option><option value="line">Close line</option></select></label><label>EMA<select id="fcEma"><option value="">None</option><option value="20">20</option><option value="50">50</option><option value="200">200</option></select></label></div><div class="market-controls"><button id="fcFit">Fit chart</button><button id="fcZoomIn">Zoom in</button><button id="fcZoomOut">Zoom out</button><button id="fcPlan">Open strategy checks & plan</button><a id="fcTv" target="_blank" rel="noopener noreferrer">Open full chart on TradingView ↗</a><a href="https://trade.fyers.in" target="_blank" rel="noopener noreferrer">Open FYERS terminal ↗</a></div><p id="fcQuote" role="status">No broker quote loaded.</p><p id="fcStatus" role="status">Ready.</p><div id="fcChart" style="height:520px"></div><p class="small-note">TradingView Lightweight Charts™ · source: FYERS. Up to 500 completed candles; the forming candle is excluded. Refresh requests a new snapshot; this is not a streaming or zero-delay feed. Scroll/pinch to zoom and drag to pan. EMA uses only loaded candles and can differ from a longer-history chart.</p><label><input id="fcAuto" type="checkbox"> Refresh chart and quote every 30 seconds while this tab is visible</label>';
 const $=id=>host.querySelector('#'+id);let chart=null,bars=[],active=true,version=0,searchVersion=0,loadId=0,busy=false;
 const status=(text,error=false)=>{$('fcStatus').textContent=text;$('fcStatus').className=error?'market-error':'market-status'};
 const sourceSymbol=()=>$('fcSymbol').value.trim().toUpperCase();
 const stamp=t=>Number.isFinite(t)?new Date(t).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST':'Source time unavailable';
 function clear(){chart?.remove();chart=null;$('fcChart').innerHTML=''}
 function link(){const s=sourceSymbol(),tv=({'NSE:NIFTY50-INDEX':'NSE:NIFTY','NSE:NIFTYBANK-INDEX':'NSE:BANKNIFTY','BSE:SENSEX-INDEX':'BSE:SENSEX'})[s]||s.replace(/-EQ$/,'');$('fcTv').href='https://www.tradingview.com/chart/?symbol='+encodeURIComponent(tv)}
 async function api(path){const r=await fetch(path,{cache:'no-store',signal:AbortSignal.timeout(25000)});let d;try{d=await r.json()}catch{throw Error('FYERS response unreadable. Check your server or sign-in.')}if(!d||typeof d!=='object'||Array.isArray(d)||!r.ok||d.error)throw Error(d?.error||'FYERS data unavailable.');return d}
 function draw(){clear();if(!bars.length){$('fcChart').textContent='No completed candles returned by FYERS for this selection.';return}const L=window.LightweightCharts;if(!L){$('fcChart').textContent='Chart library unavailable. Reload the updated app.';return}chart=L.createChart($('fcChart'),{autoSize:true,height:520,layout:{background:{type:'solid',color:'#fff'},textColor:'#253448'},localization:{timeFormatter:t=>stamp(t*1000)},timeScale:{timeVisible:$('fcResolution').value!=='D'}});const series=chart.addSeries($('fcType').value==='line'?L.LineSeries:L.CandlestickSeries,{color:'#624082',upColor:'#287f68',downColor:'#ba4e58',borderVisible:false});series.setData(bars.map(b=>$('fcType').value==='line'?{time:b.time/1000,value:b.close}:{time:b.time/1000,open:b.open,high:b.high,low:b.low,close:b.close}));const volume=chart.addSeries(L.HistogramSeries,{priceFormat:{type:'volume'},priceScaleId:'volume'});volume.priceScale().applyOptions({scaleMargins:{top:.8,bottom:0}});volume.setData(bars.map(b=>({time:b.time/1000,value:b.volume,color:b.close>=b.open?'#287f6855':'#ba4e5855'})));const n=Number($('fcEma').value);if(n&&bars.length>=n){let value=bars.slice(0,n).reduce((a,b)=>a+b.close,0)/n;const data=[{time:bars[n-1].time/1000,value}];for(const b of bars.slice(n)){value=b.close*2/(n+1)+value*(1-2/(n+1));data.push({time:b.time/1000,value})}chart.addSeries(L.LineSeries,{color:'#ab7b21',lineWidth:2,title:'EMA '+n}).setData(data)}chart.timeScale().fitContent()}
 async function load(){if(busy)return;const requestId=++loadId,token=version,s=sourceSymbol(),resolution=$('fcResolution').value;busy=true;$('fcLoad').disabled=true;clear();bars=[];status('Fetching candles and quote directly from FYERS…');const matches=()=>active&&token===version&&s===sourceSymbol()&&resolution===$('fcResolution').value;try{const results=await Promise.allSettled([api('/api/fyers/history?symbol='+encodeURIComponent(s)+'&resolution='+resolution),api('/api/fyers/quotes?symbols='+encodeURIComponent(s))]);if(!matches())return;const history=results[0],quote=results[1];if(quote.status==='fulfilled'){const q=Array.isArray(quote.value.quotes)?quote.value.quotes.find(q=>q?.symbol===s):null;$('fcQuote').textContent=q?s+': '+q.price+' · source '+stamp(q.at)+' · '+(q.valid&&Number.isFinite(q.at)&&Number.isFinite(q.price)&&q.price>0&&q.at<=Date.now()+1000&&Date.now()-q.at<=15000?'Fresh snapshot':'Last traded / not live'):'No matching FYERS quote returned.'}else $('fcQuote').textContent='Quote unavailable: '+quote.reason.message;if(history.status==='rejected')throw history.reason;const d=history.value;if(d.symbol!==s||d.resolution!==resolution||!Array.isArray(d.candles)||d.candles.some((b,i)=>!b||!['time','open','high','low','close','volume'].every(k=>Number.isFinite(b[k]))||b.time<=0||b.low<=0||b.high<Math.max(b.open,b.close)||b.low>Math.min(b.open,b.close)||b.volume<0||(i>0&&b.time<=d.candles[i-1].time)))throw Error('FYERS chart response invalid. Retry this instrument.');bars=d.candles;draw();status('FYERS · '+bars.length+' completed candles · fetched '+stamp(d.asOf)+(Number($('fcEma').value)>bars.length?' · Not enough candles for the selected EMA.':''));onSymbol(s)}catch(e){if(matches()){clear();status(e.message,true)}}finally{if(requestId===loadId){busy=false;if(active)$('fcLoad').disabled=false}}}
 function change(){version++;loadId++;busy=false;$('fcLoad').disabled=false;bars=[];clear();$('fcQuote').textContent='Selection changed. Load the chart to fetch FYERS data.';link();status('Load the selected instrument and timeframe.');onSymbol(sourceSymbol())}
 $('fcSymbol').oninput=change;$('fcResolution').onchange=change;$('fcLoad').onclick=load;$('fcType').onchange=draw;$('fcEma').onchange=draw;$('fcFit').onclick=()=>chart?.timeScale().fitContent();for(const [id,factor]of [['fcZoomIn',.7],['fcZoomOut',1.4]])$(id).onclick=()=>{const t=chart?.timeScale(),r=t?.getVisibleLogicalRange();if(r){const middle=(r.from+r.to)/2,half=(r.to-r.from)*factor/2;t.setVisibleLogicalRange({from:middle-half,to:middle+half})}};
 $('fcPlan').onclick=()=>{onSymbol(sourceSymbol());onPlan()};
 $('fcFind').onclick=async()=>{const token=++searchVersion,segment=$('fcSegment').value,search=$('fcSearch').value.trim();$('fcFind').disabled=true;$('fcResults').innerHTML='<option value="">Searching…</option>';try{const d=await api('/api/fyers/instruments?segment='+segment+'&search='+encodeURIComponent(search));if(!active||token!==searchVersion)return;if(!Array.isArray(d.instruments)||d.instruments.some(r=>!r||typeof r.symbol!=='string'||typeof r.name!=='string'))throw Error('FYERS instrument response invalid.');$('fcResults').innerHTML='<option value="">Choose an instrument</option>'+d.instruments.map(r=>'<option value="'+esc(r.symbol)+'">'+esc(r.symbol+' · '+r.name)+'</option>').join('');$('fcSearchStatus').textContent=d.total+' matches · showing first '+d.instruments.length+' · directory fetched '+stamp(d.asOf)}catch(e){if(active&&token===searchVersion){$('fcSearchStatus').textContent=e.message;$('fcResults').innerHTML='<option value="">Search again</option>'}}finally{if(active&&token===searchVersion)$('fcFind').disabled=false}};
 $('fcResults').onchange=()=>{if(!$('fcResults').value)return;$('fcSymbol').value=$('fcResults').value;change();load()};$('fcSegment').onchange=()=>{searchVersion++;$('fcFind').disabled=false;$('fcResults').innerHTML='<option value="">Search this segment</option>';$('fcSearchStatus').textContent=''};
 const timer=setInterval(()=>{if(active&&!document.hidden&&$('fcAuto').checked)load()},30000);link();load();return ()=>{active=false;version++;searchVersion++;clearInterval(timer);clear()};
}};
})();
